#ifndef HP_NATIVE_MASTER_H
#define HP_NATIVE_MASTER_H
#include <stdint.h>

/* Consume the exact argv generated by H2O's build_server_starter_argv().
 * This runs before PHP or H2O execution threads have been initialized. */
int hp_native_master_run(char *const starter_argv[], uint64_t startup_ms, uint64_t shutdown_ms);
/* Capture the inherited readiness pipe at early worker startup, before any
 * helper exec, then notify only after H2O's post-startup thread barrier. */
void hp_native_master_worker_prepare(void);
void hp_native_master_notify_ready(void);

#endif
